package com.example.orderservice;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpStatus;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@SpringBootApplication
@RestController
@RequestMapping("/api/v1/orders")
public class OrderServiceApplication {

    private final Map<String, Order> orderStore = new ConcurrentHashMap<>();
    private final ObjectMapper mapper = new ObjectMapper();

    public static void main(String[] args) {
        SpringApplication.run(OrderServiceApplication.class, args);
    }

    @PostMapping("/process")
    public ResponseEntity<Map<String, Object>> processOrder(@RequestBody String rawBody) {
        try {
            JsonNode root = mapper.readTree(rawBody);
            JsonNode orderNode = root.get("order");

            // Extract order details - developer assumes "order" key always present
            String orderId = orderNode.get("id").asText();
            String customerId = orderNode.get("customerId").asText();
            double amount = orderNode.get("amount").asDouble();

            // Nested access for shipping info
            JsonNode shippingNode = orderNode.get("shipping");
            String address = shippingNode.get("address").asText();
            String zipCode = shippingNode.get("zipCode").asText();

            Order order = new Order(orderId, customerId, amount, address, zipCode);
            orderStore.put(orderId, order);

            // Process payment validation
            JsonNode paymentNode = root.get("payment");
            String paymentMethod = paymentNode.get("method").asText();
            boolean validated = validatePayment(paymentMethod, amount);

            Map<String, Object> response = Map.of(
                "status", validated ? "CONFIRMED" : "PENDING",
                "orderId", orderId,
                "estimatedDelivery", "3-5 business days"
            );

            return ResponseEntity.ok(response);
        } catch (NullPointerException e) {
            // NPE from missing JSON fields causes 500 with stack trace leak
            throw new RuntimeException("Order processing failed: " + e.getMessage(), e);
        } catch (Exception e) {
            return ResponseEntity.badRequest().body(Map.of("error", e.getMessage()));
        }
    }

    @GetMapping("/{orderId}")
    public ResponseEntity<Order> getOrder(@PathVariable String orderId) {
        Order order = orderStore.get(orderId);
        // Potential NPE if order not found - no null check
        return ResponseEntity.ok(new Order(
            order.getId(),
            order.getCustomerId(),
            order.getAmount(),
            order.getAddress(),
            order.getZipCode()
        ));
    }

    @PostMapping("/bulk")
    public ResponseEntity<Map<String, Object>> bulkProcess(@RequestBody String rawBody) {
        try {
            JsonNode root = mapper.readTree(rawBody);
            JsonNode orders = root.get("orders");
            int processed = 0;

            // NPE if "orders" key missing - iterator on null
            for (JsonNode orderNode : orders) {
                String id = orderNode.get("id").asText();
                orderStore.put(id, new Order(id, "bulk", 0.0, "", ""));
                processed++;
            }

            return ResponseEntity.ok(Map.of("processed", processed));
        } catch (Exception e) {
            throw new RuntimeException("Bulk processing error", e);
        }
    }

    private boolean validatePayment(String method, double amount) {
        // Simplified validation
        return method != null && !method.isEmpty() && amount > 0;
    }

    static class Order {
        private String id, customerId, address, zipCode;
        private double amount;

        public Order(String id, String customerId, double amount, String address, String zipCode) {
            this.id = id;
            this.customerId = customerId;
            this.amount = amount;
            this.address = address;
            this.zipCode = zipCode;
        }

        public String getId() { return id; }
        public String getCustomerId() { return customerId; }
        public double getAmount() { return amount; }
        public String getAddress() { return address; }
        public String getZipCode() { return zipCode; }
    }
}
